<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\Controller;
use App\Core\HttpError;
use App\Core\Mailer;
final class CatalogController extends Controller {
 public function index():void{$this->view('listings',['title'=>'E’lonlar va xizmatlar katalogi','results'=>$this->store->listings($_GET,$this->user),'categories'=>$this->store->categories()]);}
 public function show():void{$x=$this->listingAccess($this->id());$attachments=[];if($this->user&&($this->user['role']!=='user'||(int)$this->user['id']===(int)$x['user_id']))$attachments=$this->store->run('SELECT * FROM attachments WHERE listing_id=?',[$x['id']])->fetchAll();$this->view('listing',['title'=>$x['title'],'item'=>$x,'attachments'=>$attachments]);}
 public function form():void{$u=$this->auth();$x=isset($_GET['id'])?$this->listingAccess($this->id(),true):null;if($x&&in_array($x['status'],['archived','blocked'],true))throw new HttpError(409,'Bloklangan yoki arxivlangan e’lon tahrirlanmaydi.');$this->view('listing-form',['title'=>$x?'E’lonni tahrirlash':'Yangi e’lon','item'=>$x,'categories'=>$this->store->categories()]);}
 public function save():void{$this->post();$u=$this->auth();$id=empty($_POST['id'])?null:$this->id('id',true);$old=$id?$this->listingAccess($id,true):null;$title=$this->text('title',5,120);$description=$this->text('description',15,5000);$city=$this->text('city',2,80);if(!in_array($city,['Toshkent','Samarqand','Buxoro','Andijon','Farg‘ona','Namangan'],true))throw new HttpError(422,'Hududni ro‘yxatdan tanlang.');$category=$this->id('category_id',true);if(!$this->store->find('categories',$category))throw new HttpError(422,'Toifa mavjud emas.');$price=filter_var($_POST['price']??'',FILTER_VALIDATE_FLOAT);if($price===false||$price<0||$price>999999999999)throw new HttpError(422,'Narx 0–999999999999 oralig‘ida bo‘lsin.');$phone=$this->text('phone',9,25);if(!preg_match('/^\+?[0-9 ()-]{9,24}$/D',$phone))throw new HttpError(422,'Telefon raqami noto‘g‘ri.');$expires=$this->text('expires_at',10,10);$date=\DateTimeImmutable::createFromFormat('!Y-m-d',$expires);if(!$date||$date->format('Y-m-d')!==$expires||$date<new \DateTimeImmutable('today')||$date>new \DateTimeImmutable('+180 days'))throw new HttpError(422,'Muddat bugundan boshlab 180 kun oralig‘ida bo‘lsin.');$expiry=$expires.' 23:59:59';
 if($id){$this->store->db->beginTransaction();try{$locked=$this->store->run('SELECT * FROM listings WHERE id=? FOR UPDATE',[$id])->fetch();if(!$locked||in_array($locked['status'],['blocked','archived'],true))throw new HttpError(409,'E’lon holati tahrirlashga ruxsat bermaydi.');if($u['role']!=='admin'&&(int)$locked['user_id']!==(int)$u['id'])throw new HttpError(403,'Egalik huquqi yo‘q.');$this->store->run('UPDATE listings SET title=?,description=?,city=?,category_id=?,price=?,phone=?,expires_at=? WHERE id=?',[$title,$description,$city,$category,$price,$phone,$expiry,$id]);$this->store->db->commit();}catch(\Throwable $e){$this->store->db->rollBack();throw $e;}}
 else{$this->store->run('INSERT INTO listings(user_id,category_id,title,description,city,price,phone,expires_at) VALUES(?,?,?,?,?,?,?,?)',[$u['id'],$category,$title,$description,$city,$price,$phone,$expiry]);$id=(int)$this->store->db->lastInsertId();}flash('E’lon saqlandi. Fayllarni quyida biriktirishingiz mumkin.');redirect('listing',['id'=>$id]);}
 public function delete():void{$this->post();$u=$this->auth();$id=$this->id('id',true);$this->listingAccess($id,true);if(($_POST['confirm']??'')!=='yes')throw new HttpError(422,'Arxivlashni tasdiqlang.');$this->store->run('UPDATE listings SET status="archived" WHERE id=?',[$id]);flash('E’lon arxivlandi. Shikoyat va qarorlar tarixi saqlandi.');redirect();}
 public function extend():void{$this->post();$u=$this->auth();$this->store->lifecycle($this->id('id',true),$u,'extend',$this->text('expected_expires_at',19,19));flash('Muddat 30 kunga uzaytirildi.');redirect('listing',['id'=>(int)$_POST['id']]);}
 public function expire():void{$this->post();$u=$this->auth();$this->store->lifecycle($this->id('id',true),$u,'expire',$this->text('expected_expires_at',19,19));flash('E’lon muddati tugatildi.');redirect('listing',['id'=>(int)$_POST['id']]);}
 public function categories():void{$this->view('categories',['title'=>'Toifalar','items'=>$this->store->categories()]);}
 public function category():void{$item=$this->store->find('categories',$this->id());if(!$item)throw new HttpError(404,'Toifa topilmadi.');$this->view('category',['title'=>$item['name'],'item'=>$item]);}
 public function categoryForm():void{$this->auth(['admin']);$item=isset($_GET['id'])?$this->store->find('categories',$this->id()):null;if(isset($_GET['id'])&&!$item)throw new HttpError(404,'Toifa topilmadi.');$this->view('category-form',['title'=>$item?'Toifani tahrirlash':'Yangi toifa','item'=>$item]);}
 public function categorySave():void{$this->post();$this->auth(['admin']);$id=empty($_POST['id'])?null:$this->id('id',true);if($id&&!$this->store->find('categories',$id))throw new HttpError(404,'Toifa topilmadi.');$name=$this->text('name',2,80);$description=$this->text('description',5,500);if($this->store->run('SELECT id FROM categories WHERE name=? AND id<>?',[$name,$id??0])->fetch())throw new HttpError(422,'Bu toifa nomi band.');if($id)$this->store->run('UPDATE categories SET name=?,description=? WHERE id=?',[$name,$description,$id]);else{$this->store->run('INSERT INTO categories(name,description) VALUES(?,?)',[$name,$description]);$id=(int)$this->store->db->lastInsertId();}flash('Toifa saqlandi.');redirect('category',['id'=>$id]);}
 public function categoryDelete():void{$this->post();$this->auth(['admin']);$id=$this->id('id',true);if(!$this->store->find('categories',$id))throw new HttpError(404,'Toifa topilmadi.');if(($_POST['confirm']??'')!=='yes')throw new HttpError(422,'O‘chirishni tasdiqlang.');if($this->store->run('SELECT id FROM listings WHERE category_id=? LIMIT 1',[$id])->fetch())throw new HttpError(409,'Toifaga bog‘langan e’lon mavjud. Avval ularni boshqa toifaga o‘tkazing.');$this->store->run('DELETE FROM categories WHERE id=?',[$id]);flash('Toifa o‘chirildi.');redirect('categories');}
 public function complaints():void{$u=$this->auth();$this->view('complaints',['title'=>'Shikoyatlar','items'=>$this->store->complaints($u)]);}
 public function complain():void{$this->post();$u=$this->auth();$id=$this->id('listing_id',true);$x=$this->listingAccess($id);if((int)$x['user_id']===(int)$u['id'])throw new HttpError(422,'O‘z e’loningizga shikoyat yubora olmaysiz.');if(effective_status($x)!=='active')throw new HttpError(409,'Faqat faol e’longa shikoyat yuboriladi.');$reason=$this->text('reason',15,2000);if($this->store->run('SELECT id FROM complaints WHERE user_id=? AND listing_id=?',[$u['id'],$id])->fetch())throw new HttpError(409,'Bu e’lon bo‘yicha shikoyatingiz mavjud.');$this->store->run('INSERT INTO complaints(listing_id,user_id,reason) VALUES(?,?,?)',[$id,$u['id'],$reason]);flash('Shikoyatingiz moderatorga yuborildi.');redirect('complaints');}
 public function decide():void{$this->post();$u=$this->auth(['admin','moderator']);$outcome=$_POST['outcome']??'';if(!in_array($outcome,['approved','rejected'],true))throw new HttpError(422,'Qaror noto‘g‘ri.');$this->store->decide($this->id('id',true),$u,$outcome,$this->text('note',10,2000));flash('Qaror saqlandi.');redirect('decisions');}
 public function decisions():void{$u=$this->auth();$this->view('decisions',['title'=>'Tekshirish qarorlari','items'=>$this->store->decisions($u)]);}
 public function export():void{$u=$this->auth();$rows=$this->store->listings($_GET,$u,true)['items'];header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="yaqin-listings.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');fputcsv($out,['ID','Sarlavha','Toifa','Hudud','Narx','Holat','Muddat'],',','"','');foreach($rows as $x){$row=[$x['id'],$x['title'],$x['category_name'],$x['city'],$x['price'],effective_status($x),$x['expires_at']];$row=array_map(fn($v)=>preg_match('/^[\s\x00-\x1F]*[=+@-]/u',(string)$v)?"'".$v:$v,$row);fputcsv($out,$row,',','"','');}fclose($out);}
 public function contact():void{if($_SERVER['REQUEST_METHOD']==='POST'){$this->post();$name=$this->text('name',2,80);$email=$this->text('email',3,190);if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new HttpError(422,'Email noto‘g‘ri.');$message=$this->text('message',10,5000);$hash=hash('sha256',$_SERVER['REMOTE_ADDR']??'local');if($this->store->run('SELECT id FROM contact_messages WHERE ip_hash=? AND created_at>DATE_SUB(NOW(),INTERVAL 60 SECOND) LIMIT 1',[$hash])->fetch())throw new HttpError(429,'Keyingi xabarni 60 soniyadan keyin yuboring.');$this->store->run('INSERT INTO contact_messages(name,email,message,ip_hash) VALUES(?,?,?,?)',[$name,$email,$message,$hash]);$id=(int)$this->store->db->lastInsertId();$sent=Mailer::send($name,$email,$message);$this->store->run('UPDATE contact_messages SET smtp_status=? WHERE id=?',[$sent?'sent':'failed',$id]);flash($sent?'Xabar saqlandi va pochta serveriga yuborildi.':'Xabar bazada saqlandi. Pochta yuborilmadi; administrator xabarni ko‘ra oladi.');redirect('contact');}$messages=$this->user&&$this->user['role']==='admin'?$this->store->run('SELECT * FROM contact_messages ORDER BY id DESC')->fetchAll():[];$this->view('contact',['title'=>'Biz bilan bog‘lanish','items'=>$messages]);}
}
